// List puts a name up for sale at a price in ugnot.
//
// It does NOT take the name. The seller keeps it, keeps using it, and
// keeps the right to change their mind.
//
// The approval is required BEFORE listing rather than checked only at
// sale time, so a listing that could never complete cannot exist. A
// buyer finding out at the checkout that the seller never approved
// anything is the worst moment to find out.
func List(cur realm, tid string, price int64) {
	assertNoSend()
	seller := cur.Previous().Address()
	label, domainLabel := splitTokenID(tid)
	if label == "" || domainLabel == "" {
		panic("nsmarket: a token id looks like label*domain")
	}
	if strings.HasPrefix(tid, "*") {
		panic("nsmarket: domains are project-owned and not for sale")
	}
	if price < minPrice || price > maxPrice {
		panic("nsmarket: price out of range")
	}
	if !nsdata.NameExists(label, domainLabel) {
		panic("nsmarket: no such name")
	}
	// A frozen name should not sit on the marketplace advertising itself.
	// nslogic.TransferFrom refuses it anyway; a buyer should not find out
	// by paying.
	_, registered, _, _, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
	if frozen {
		panic("nsmarket: this name is frozen and cannot be listed or sold")
	}
	if nsdata.GetNameOwner(label, domainLabel) != seller {
		panic("nsmarket: only the owner may list a name")
	}
	// An expired name cannot be transferred, so it cannot be sold. Saying
	// so here rather than letting somebody list it and take an offer.
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nsmarket: this name has expired — renew it before selling it")
	}
	if !nsdata.IsNameNFT(label, domainLabel) {
		panic("nsmarket: this name has no token yet; mint one before selling it")
	}
	// Panics with the vault's own error when there is no per-token
	// approval at all — a refusal either way.
	if !approvedTo(cur.Address(), tid) {
		panic("nsmarket: approve the marketplace for this name first (Approve, for this one name — a blanket operator approval does not count here), so a sale can complete in one transaction")
	}

	listings.Set(tid, &Listing{seller: seller, price: price,
		listed: time.Now().Unix(), registered: registered})
	chain.Emit("Listed", "tid", tid, "price", ufmt.Sprintf("%d", price), "seller", seller.String())
}

// Unlist withdraws a listing. The seller, or the admin for a name that
// should not be on sale at all — the same manual lever the takedown
// process already relies on elsewhere.
func Unlist(cur realm, tid string) {
	assertNoSend()
	caller := cur.Previous().Address()
	l := get(tid)
	if l == nil {
		panic("nsmarket: not listed")
	}
	if caller != l.seller && caller != nsdata.GetAdmin() {
		panic("nsmarket: only the seller may withdraw a listing")
	}
	listings.Remove(tid)
	chain.Emit("Unlisted", "tid", tid)
}

/*
Prune clears a listing that can no longer complete. Anyone may call it.

WHY ANYONE. A listing goes stale without this realm hearing about it: the
name is transferred elsewhere, lapses, is frozen, or the seller points the
approval somewhere else. Buy refuses such a listing — but a refusal is a
panic, and a panic reverts everything, including the attempt to delete the
listing on the way out. v3 did exactly that: it removed the listing,
panicked with "the listing is gone", and the revert put the listing back.
Found on the Pearl sandbox, 2026-09-10.

ONE CASE PRUNE CANNOT CLEAR: a name that left the seller and came back.
Every transfer wipes the per-token approval, and nsdata/v1's GetApproved
panics when there is none — a panic nothing here can catch. That listing
still cannot SELL (Buy panics the same way), so it is harmless; the seller
or the admin removes it with Unlist.

The pruner gains only the listing's storage deposit, which the chain
refunds to whoever frees storage. staleReason must name a reason or
Prune refuses, so the only thing it can remove is a listing already dead.
*/
func Prune(cur realm, tid string) {
	assertNoSend()
	l := get(tid)
	if l == nil {
		panic("nsmarket: not listed")
	}
	why := staleReason(cur.Address(), tid, l, true)
	if why == "" {
		panic("nsmarket: this listing can still complete — only the seller may withdraw it")
	}
	listings.Remove(tid)
	chain.Emit("Pruned", "tid", tid, "reason", why)
}

// Buy completes a sale in the buyer's own transaction.
//
// Order matters here. Everything that can refuse the sale is checked
// before a single coin moves, and the name moves before the money does,
// so there is no arrangement of failures that leaves the seller paid and
// the buyer empty-handed. A panic anywhere reverts all of it.
func Buy(cur realm, tid string) {
	if !cur.Previous().IsUserCall() {
		panic("nsmarket: only direct wallet calls may buy")
	}
	buyer := cur.Previous().Address()
	l := get(tid)
	if l == nil {
		panic("nsmarket: not listed")
	}
	// The world can have moved since the listing was written. The refusal
	// cannot also delete the listing — see Prune for why.
	if why := staleReason(cur.Address(), tid, l, true); why != "" {
		panic("nsmarket: " + why + " — this listing can no longer complete (anyone may clear it with Prune)")
	}
	if buyer == l.seller {
		panic("nsmarket: you already own this")
	}

	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nsmarket: only ugnot is accepted, got: " + c.Denom)
		}
	}
	paid := sent.AmountOf(ugnot)
	if paid < l.price {
		panic(ufmt.Sprintf("nsmarket: %d ugnot short of the asking price", l.price-paid))
	}

	// The name first. If this fails nothing has been paid out yet, and
	// the revert takes the buyer's coins back with it.
	nslogic.TransferFrom(cross(cur), l.seller, buyer, tid)

	fee, toSeller := FeeFor(l.price)
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := cur.Address()
	if toSeller > 0 {
		b.SendCoins(self, l.seller, chain.Coins{chain.NewCoin(ugnot, toSeller)})
	}
	if fee > 0 {
		b.SendCoins(self, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, fee)})
	}
	if excess := paid - l.price; excess > 0 {
		b.SendCoins(self, buyer, chain.Coins{chain.NewCoin(ugnot, excess)})
	}

	listings.Remove(tid)
	sold++
	chain.Emit("Sold", "tid", tid, "price", ufmt.Sprintf("%d", l.price),
		"seller", l.seller.String(), "buyer", buyer.String(),
		"fee", ufmt.Sprintf("%d", fee))
}

// -- helpers --

func get(tid string) *Listing {
	v := listings.Get(tid)
	if v == nil {
		return nil
	}
	return v.(*Listing)
}

/*
staleReason says why a listing can no longer complete, or "" when it can.

ONE ANSWER FOR THREE CALLERS: Buy refuses on it, Prune clears on it, the
reads report live=false on it.

withApproval is false for the READS, and that is forced, not chosen.
nsdata/v1's GetApproved panics for a token with no per-token approval, and
recover() does not catch a panic raised inside another realm's function
(tested 2026-09-14, non-crossing call included). Every transfer wipes the
approval, so a seller who lists, sends the name to a second wallet and
back would make one row panic — and ListForSale, the whole marketplace
page, with it, for everyone. So the reads stay blind to a withdrawn
approval; the site checks each listing's approval itself (market.js), where
a failed query is just an answer. Buy and Prune may panic: for them a panic
is a refusal.
*/
func staleReason(self address, tid string, l *Listing, withApproval bool) string {
	label, domainLabel := splitTokenID(tid)
	if !nsdata.NameExists(label, domainLabel) {
		return "this name no longer exists"
	}
	_, registered, _, _, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
	if frozen {
		return "this name is frozen"
	}
	if nsdata.GetNameOwner(label, domainLabel) != l.seller {
		return "this name has changed hands since it was listed"
	}
	if !nsdata.IsNameValid(label, domainLabel) {
		return "this name has expired"
	}
	if l.registered != 0 && registered != l.registered {
		return "this name lapsed and was registered again since it was listed"
	}
	if withApproval && !approvedTo(self, tid) {
		return "the seller has withdrawn permission"
	}
	return ""
}

/*
Whether this realm holds the PER-TOKEN approval for the name. Panics (the
vault's error) when the token has no per-token approval at all.

ONLY THE PER-TOKEN APPROVAL COUNTS, unlike v3, which also accepted an
operator grant (SetApprovalForAll). This vault has no ownership epoch, and
an operator grant survives transfers — so under one, a name listed, sold
elsewhere and bought back had its old listing complete again at the old
price, and a listing "cancelled" by withdrawing the approval came back the
day the seller granted an operator approval for anything else. A per-token
approval is wiped by every transfer, so it cannot outlive the ownership it
was given under. The site only ever asks for per-token approval.
*/
func approvedTo(self address, tid string) bool {
	return nsdata.GetApproved(grc721.TokenID(tid)) == self
}

func splitTokenID(tid string) (label, domainLabel string) {
	at := strings.Index(tid, "*")
	if at < 1 || at == len(tid)-1 {
		return "", ""
	}
	return tid[:at], tid[at+1:]
}

// This realm takes no payment on anything except Buy.
func assertNoSend() {
	if !unsafe.OriginSend().IsZero() {
		panic("nsmarket: this function takes no payment; do not attach coins")
	}
}

package nsmarket

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// Reads for the site. Rows are ";"-separated records of
// "label*domain,price,seller,listed,live" where `live` is false when the
// listing has gone stale under it — the seller moved the name, let it
// lapse, or withdrew permission.
//
// Stale listings are REPORTED, not hidden and not silently deleted.
// Hiding them makes a seller's page lie about what they have up; and
// deleting them would mean a read function writing to storage, which is
// how a query starts costing gas. Prune is the write that clears them.
//
// `live` does NOT include the approval — see staleReason for why it cannot
// on this vault. The site checks approvals itself.

func row(tid string, l *Listing) string {
	live := staleReason("", tid, l, false) == ""
	return ufmt.Sprintf("%s,%d,%s,%d,%t", tid, l.price, l.seller.String(), l.listed, live)
}

// GetListing returns one row, or "" when nothing is listed.
func GetListing(tid string) string {
	l := get(tid)
	if l == nil {
		return ""
	}
	return row(tid, l)
}

// ListForSale pages through everything on offer, cheapest first within a
// page. `after` is the last token id of the previous page.
func ListForSale(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	var out []string
	var last string
	listings.Iterate(after, "", func(key string, v any) bool {
		if key == after {
			return false // the cursor is exclusive
		}
		out = append(out, row(key, v.(*Listing)))
		last = key
		return len(out) >= limit
	})
	if len(out) < limit {
		last = "" // the end; no cursor to hand back
	}
	return strings.Join(out, ";"), last
}

// ListingsBy is everything one wallet has up for sale. Walks the whole
// tree because listings are keyed by token id, not by seller: a second
// index would be a second thing to keep correct and a second thing the
// seller pays storage for, to save a walk over a list that is small by
// construction.
func ListingsBy(seller address) string {
	var out []string
	listings.Iterate("", "", func(key string, v any) bool {
		l := v.(*Listing)
		if l.seller == seller {
			out = append(out, row(key, l))
		}
		return false
	})
	return strings.Join(out, ";")
}

func CountListed() int64 { return int64(listings.Size()) }
func CountSold() int64   { return sold }

// Quote is what a buyer pays and what the seller receives, before
// anybody signs anything. The fee is read live, so this is the same
// arithmetic Buy will do rather than a copy of it that can drift.
func Quote(tid string) (price, fee, toSeller int64) {
	l := get(tid)
	if l == nil {
		return 0, 0, 0
	}
	f, s := FeeFor(l.price)
	return l.price, f, s
}

// Version lets the site tell which shape it is talking to without
// guessing from a function signature.
func Version() string { return "v4" }

// nsmarket — names for sale, without anybody holding anything.
//
// THIS IS THE PRODUCTION GENERATION'S MARKETPLACE: the one that runs against
// nsdata/v1 and nslogic/v4 under g1xr6tgx...meme. realm/nsmarket is the
// second attempt's, which settles on nsnft; the two cannot share a source
// because the vaults they read are different shapes. Deploy with
// tools/deploy-prod-market.sh.
//
// HOW A SALE WORKS, and why it is built this way.
//
// The seller keeps their name. Listing does not move it here: it records
// an asking price and relies on the GRC-721 approval the seller has
// already granted this realm. Ownership does not change until somebody
// buys, and the seller can walk away at any moment by withdrawing the
// approval — at which point the listing can no longer complete.
//
// The buyer's money is never held either. Buy is ONE call: it checks the
// listing still stands, moves the name, pays the seller, takes the fee,
// refunds any overpayment. All of it inside the transaction the buyer
// signed. If any part fails the whole thing reverts and nothing moved.
//
// Which means: at no point does this realm hold somebody else's name or
// somebody else's money. That is not a nice-to-have. An escrow that
// holds either one is a different kind of business, with a different set
// of rules, run by people with licences.
//
// THIS REALM HAS NO VAULT PRIVILEGES. It is not in nsdata's trusted set
// and does not ask to be. Every transfer goes through nslogic's ordinary
// GRC-721 path, which means it can only move a name the owner has
// explicitly approved — the same permission any other marketplace would
// need. However wrong the code below turns out to be, the worst it can
// do is fail.
package nsmarket

import (
	"gno.land/p/nt/avl/v0"
)

// A listing. Kept small on purpose: the seller pays to store it, and
// everything derivable is derived rather than copied. The seller's
// address is here because the name can change hands outside this realm
// and a stale seller must be caught, not trusted.
type Listing struct {
	seller address
	price  int64 // ugnot
	listed int64 // unix seconds
	/* PINNED TO ONE REGISTRATION, the same way nsskin pins a binding.
	   Without it a listing outlives the registration it was made
	   against: list, let the name lapse, re-register it yourself, and a
	   passer-by executes the year-old listing against the name you just
	   paid to get back. Zero means a listing written before this field,
	   treated as unpinned. */
	registered int64
}

var (
	// Keyed by token id, "label*domain".
	listings avl.Tree
	sold     int64 // completed sales, for the honest version of a stat
)

/*
WHO PAYS FOR A LISTING'S STORAGE, AND WHO GETS IT BACK. Measured on Pearl,
2026-09-10. The seller's List transaction pays the storage deposit for the
listing. The chain refunds a deposit to whoever's transaction FREES the
storage, so when Buy removes the listing the refund goes to the BUYER
(about 0.31 GNOT). Unlist refunds the seller, and Prune refunds whoever
prunes. This is gno's rule and cannot be routed elsewhere.
*/

const (
	maxPage  = 200
	minPrice = int64(1)       // zero would be a giveaway, not a sale
	maxPrice = int64(1) << 52 // guards the fee arithmetic from overflow
	ugnot    = "ugnot"
)

// Package campaign is a small, deliberately TEMPORARY realm: it holds
// a wallet allowlist for discounted gems4 mints (wallet -> {bps,
// remainingUses}), separate from ../stable (which never intends to
// shrink) specifically so this list can be pruned and its storage
// deposit recovered once a campaign ends.
//
// Why a dedicated realm instead of a Merkle root (the gems3 approach)
// or a bigger avl.Tree inside stable itself: a real avl.Tree entry
// here costs ~0.22 GNOT in storage deposit (measured live on Pearl,
// 2026-09-14) -- for a few hundred wallets that's real money (~99
// GNOT for the original 441-wallet list), which is exactly why gems3
// moved to a Merkle root instead. But that deposit is NOT a burn: gno
// refunds it automatically the instant the underlying bytes are
// deleted (same mechanism ../stable's own Burn relies on). So each
// wallet's entry self-refunds the moment it's fully redeemed
// (ConsumeDiscount deletes it once RemainingUses hits zero), and
// anything left unredeemed when the campaign closes can be swept with
// RemoveWalletsBatch to recover the rest. Net effect: closer to a
// refundable deposit than a real cost, in exchange for a much simpler
// mint-time check (a direct lookup, no proofs, no off-chain file to
// host or keep in sync).
package campaign

import (
	unsaferealm "chain/runtime/unsafe"
	"strings"

	"gno.land/p/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/avl"
)

var (
	// collectionOwner is the only address allowed to manage the
	// allowlist. Same address as gems4/stable's own collectionOwner.
	collectionOwner address = "g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku"

	// approvedConsumer is the one realm allowed to call
	// ConsumeDiscount -- set once to gems4/stable's own pkgpath (never
	// gems4/v1's), specifically so this gate never needs to change on
	// a future mint-mechanics version swap. stable is the permanent
	// half of the split; pinning the gate there means campaign's own
	// wiring survives v1 -> v2 -> ... redeploys with zero changes.
	approvedConsumer string

	entries avl.Tree // wallet.String() -> *entry
)

// entry is stored BY POINTER so ConsumeDiscount can decrement
// RemainingUses in place; every mutation still goes through
// entries.Set to guarantee the change persists regardless of how gno's
// realm storage treats pointer aliasing internally.
type entry struct {
	Bps           int64
	RemainingUses int64
}

func callerAddress() address {
	return unsaferealm.PreviousRealm().Address()
}

func assertOwner() {
	if callerAddress() != collectionOwner {
		panic("unauthorized: caller is not the collection owner")
	}
}

// SetApprovedConsumer is called once, right after gems4/stable is
// deployed, to point this realm's discount-consuming gate at it.
func SetApprovedConsumer(cur realm, pkgpath string) {
	assertOwner()
	approvedConsumer = pkgpath
}

func validateBps(bps int64) {
	if bps < 0 || bps > 10000 {
		panic("bps must be between 0 and 10000")
	}
}

func validateMaxUses(maxUses int64) {
	if maxUses <= 0 {
		panic("maxUses must be positive")
	}
}

// AddWallet grants (or replaces) one wallet's discount: bps off the
// standard price, usable maxUses times before falling back to
// standard pricing.
func AddWallet(cur realm, wallet address, bps int64, maxUses int64) {
	assertOwner()
	validateBps(bps)
	validateMaxUses(maxUses)
	entries.Set(wallet.String(), &entry{Bps: bps, RemainingUses: maxUses})
}

// AddWalletsBatch grants the SAME (bps, maxUses) pair to every wallet
// in a comma-separated list -- for populating one tier (e.g. all
// Tardigrade holders) in as few transactions as possible. Keep
// batches small enough to fit gno_call's default deposit ceiling; see
// this project's own notes on gnomcp's missing max_deposit control.
func AddWalletsBatch(cur realm, walletsCSV string, bps int64, maxUses int64) {
	assertOwner()
	validateBps(bps)
	validateMaxUses(maxUses)
	for _, w := range strings.Split(walletsCSV, ",") {
		w = strings.TrimSpace(w)
		if w == "" {
			continue
		}
		entries.Set(w, &entry{Bps: bps, RemainingUses: maxUses})
	}
}

// RemoveWallet deletes one wallet's entry outright (whether or not
// they've used it), refunding its storage deposit to whoever calls
// this.
func RemoveWallet(cur realm, wallet address) {
	assertOwner()
	entries.Remove(wallet.String())
}

// RemoveWalletsBatch sweeps a batch of wallets at once -- for closing
// out a campaign and recovering deposit from everyone who never
// redeemed. Batched for the same reason AddWalletsBatch is: a single
// call covering hundreds of wallets can exceed gno_call's default
// deposit/gas ceiling.
func RemoveWalletsBatch(cur realm, walletsCSV string) {
	assertOwner()
	for _, w := range strings.Split(walletsCSV, ",") {
		w = strings.TrimSpace(w)
		if w == "" {
			continue
		}
		entries.Remove(w)
	}
}

func assertCallerIsApprovedConsumer(cur realm) {
	caller := cur.Previous().PkgPath()
	if approvedConsumer == "" || caller != approvedConsumer {
		panic("unauthorized: caller is not the approved consumer realm")
	}
}

// Peek reports wallet's current discount WITHOUT consuming it -- for
// computing a price preview before a real mint actually happens. Pure
// read, callable by anyone/anything (no gate): looking at the price
// list isn't a privileged action, only spending an entry is.
func Peek(wallet address) (bps int64, remainingUses int64, ok bool) {
	raw := entries.Get(wallet.String())
	e, isEntry := raw.(*entry)
	if !isEntry {
		return 0, 0, false
	}
	return e.Bps, e.RemainingUses, true
}

// ConsumeDiscount spends one use of wallet's discount, called only by
// the approved consumer (gems4/stable) atomically during a real mint.
// Deletes the entry once uses reach zero -- that deletion is what
// triggers gno's automatic storage-deposit refund (see this package's
// own doc comment), so a fully-redeemed wallet's deposit comes back on
// its own, no manual sweep needed. Returns ok=false with no state
// change if wallet has no entry (e.g. they paid standard price, or
// used stable's separate individual-override list instead).
func ConsumeDiscount(cur realm, wallet address) (bps int64, ok bool) {
	assertCallerIsApprovedConsumer(cur)
	raw := entries.Get(wallet.String())
	e, isEntry := raw.(*entry)
	if !isEntry {
		return 0, false
	}
	e.RemainingUses--
	if e.RemainingUses <= 0 {
		entries.Remove(wallet.String())
	} else {
		entries.Set(wallet.String(), e)
	}
	return e.Bps, true
}

func Count() int64 { return int64(entries.Size()) }

func EntryAt(index int) (wallet string, bps int64, remainingUses int64) {
	w, v := entries.GetByIndex(index)
	e := v.(*entry)
	return w, e.Bps, e.RemainingUses
}

// Package stable is the permanent, never-redeployed half of the Gems
// split-realm design -- the fourth iteration of this spike (gems ->
// gems2 -> gems3 -> gems4):
//
//   - Ownership + transfers + burn (Approve/TransferFrom/
//     SafeTransferFrom/SetApprovalForAll/Burn) -- an NFT people can't
//     move or sell isn't real. Burning RELEASES that token's trait
//     combination back into the available pool and its storage
//     deposit refunds automatically via gno's own storage-accounting
//     the moment the freed bytes are deleted, no custom refund logic
//     needed.
//   - mintedTraitCombos (trait-uniqueness history) lives HERE, not in
//     the swappable version realm -- so a future version redeploy can
//     never accidentally re-mint an already-used combination.
//   - A full gnoweb Render(), matching the original single-realm
//     design's home page / page/N / token/ID / burned pages exactly.
//   - Pricing/discount now reads from ../campaign (2026-09-14, this
//     iteration) instead of gems3's Merkle-root allowlist: campaign
//     is a small, deliberately temporary realm holding wallet ->
//     {bps, remainingUses}, prunable and storage-deposit-refundable
//     once a campaign ends. whitelistBps here still exists separately
//     for the rare permanent individual override (a handful of
//     wallets, not a campaign-sized list) and takes precedence over
//     campaign when both apply -- see EffectivePrice/RecordMint.
//
// Mint MECHANICS (trait assembly, art rendering, chain roster) still
// live in the paired version realm (e.g. gems4/v1) and can be
// redeployed and re-approved at will, with zero holder migration,
// because ownership/pricing/uniqueness-history never move.
package stable

import (
	runtime "chain/runtime"
	unsaferealm "chain/runtime/unsafe"
	"encoding/base64"
	"strconv"
	"strings"

	"gno.land/p/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/avl"
	grc721 "gno.land/p/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/grc721v2"
	campaign "gno.land/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/gems4/campaign"
	"gno.land/p/nt/ufmt/v0"
)

const (
	CollectionName   = "Gems"
	CollectionSymbol = "GEMS"

	// realmRelPath is this realm's own gnoweb-relative path, baked in
	// as a compile-time constant -- see the original single-realm
	// design's own comment on why (chain/runtime/unsafe.CurrentRealm()
	// resolves differently when called nested inside Render than when
	// called directly). Must be updated by hand if this realm is ever
	// redeployed to a new path.
	realmRelPath = "/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/gems4/stable"

	homeRenderLimit    = 10
	pageWindow         = 2
	tokenPageImageSize = "420"
)

var (
	nft *grc721.MetadataNFT

	// collectionOwner is the only address allowed to change pricing,
	// the whitelist, or which version realm is approved.
	collectionOwner address = "g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku"

	// approvedVersion is the full pkgpath of the ONE realm currently
	// allowed to call RecordMint.
	approvedVersion string

	mintPriceUgnot int64 = 1_000_000

	// whitelistBps: PERMANENT per-wallet price overrides, for a
	// handful of one-off grants (team, partners) that should never
	// expire or get swept -- unlike ../campaign, which is meant to be
	// pruned. Takes precedence over campaign when a wallet has both
	// (see EffectivePrice/RecordMint).
	whitelistBps avl.Tree

	// mintedIDs is an append-only record of every token minted here, in
	// mint order.
	mintedIDs []grc721.TokenID

	// mintedTraitCombos is the PERMANENT (well -- see Burn) record of
	// which exact trait combinations have been minted, moved here from
	// the version realm so uniqueness history survives any future
	// version redeploy. Reserved by RecordMint, released by Burn.
	mintedTraitCombos avl.Tree // combo key -> true

	// tokenComboKeys remembers which comboKey RecordMint reserved for
	// each token, so Burn can release the EXACT same key -- comboKey is
	// an opaque string built by whichever version realm minted the
	// token (from its own raw trait indices, not anything stable can
	// reconstruct from display metadata), so it has to be stored
	// verbatim rather than recomputed.
	tokenComboKeys avl.Tree // tid.String() -> comboKey string

	// mintCountByWallet tracks mints per recipient, moved here for the
	// same reason -- a version swap must not reset anyone's cap usage.
	mintCountByWallet avl.Tree // address.String() -> int64

	// mintingOpenMirror/maxMintsPerWalletMirror are DISPLAY-ONLY copies
	// of settings the approved version realm actually enforces -- gno
	// doesn't allow circular imports, so stable (which v1 imports)
	// cannot import v1 back to read its live mintingOpen/
	// maxMintsPerWallet directly. The version realm calls
	// ReportMintingOpen/ReportMaxMintsPerWallet (version-gated, same
	// pattern as RecordMint) whenever it changes them, purely so
	// Render() here can show accurate values without a circular
	// dependency.
	mintingOpenMirror       = true
	maxMintsPerWalletMirror int64 = 3

	// burnedRecords/burnedIDs are a permanent record of every token
	// this realm has ever burned.
	burnedRecords avl.Tree // tid.String() -> burnRecord
	burnedIDs     []grc721.TokenID
)

// traitPreset mirrors the version realm's own traitPreset field-for-
// field -- needed here only to reconstruct a burned token's display
// metadata on demand, the same trick the original single-realm design
// used to avoid storing a second copy of the rendered image.
type traitPreset struct {
	Chain    string
	ShapeIdx int
	ColorIdx int
	Metal    string
	Active   bool
}

// burnRecord is a permanent snapshot of one burned token.
type burnRecord struct {
	BurnedBy   address
	BurnHeight int64
	Metadata   grc721.Metadata
}

func init(cur realm) {
	nft = grc721.NewNFTWithMetadata(0, cur, CollectionName, CollectionSymbol)
}

/* ------------------------------ standard reads ------------------------------ */

func Name() string      { return CollectionName }
func Symbol() string    { return CollectionSymbol }
func TokenCount() int64 { return nft.TokenCount() }

func OwnerOf(tid grc721.TokenID) (address, error)                { return nft.OwnerOf(tid) }
func BalanceOf(owner address) (int64, error)                     { return nft.BalanceOf(owner) }
func TokenMetadata(tid grc721.TokenID) (grc721.Metadata, error)   { return nft.TokenMetadata(tid) }
func TokenURI(tid grc721.TokenID) (string, error)                 { return nft.TokenURI(tid) }
func GetApproved(tid grc721.TokenID) (address, error)             { return nft.GetApproved(tid) }
func IsApprovedForAll(owner, operator address) bool               { return nft.IsApprovedForAll(owner, operator) }

func ApprovedVersion() string { return approvedVersion }
func Owner() address          { return collectionOwner }
func MintPrice() int64        { return mintPriceUgnot }

func MintedIDs() []grc721.TokenID { return mintedIDs }
func TotalBurned() int64          { return int64(len(burnedIDs)) }

func MintingOpen() bool        { return mintingOpenMirror }
func MaxMintsPerWallet() int64 { return maxMintsPerWalletMirror }

func MintsByWallet(owner address) int64 {
	n, _ := mintCountByWallet.Get(owner.String()).(int64)
	return n
}

func IsTraitComboAvailable(comboKey string) bool {
	return !mintedTraitCombos.Has(comboKey)
}

// WhitelistBps reports wallet's PERMANENT individual price override in
// basis points, and whether it has one (ok == false means: check
// ../campaign, or pay standard price).
func WhitelistBps(wallet address) (bps int64, ok bool) {
	if !whitelistBps.Has(wallet.String()) {
		return 0, false
	}
	return whitelistBps.Get(wallet.String()).(int64), true
}

func WhitelistCount() int64 { return int64(whitelistBps.Size()) }

func WhitelistEntry(index int) (wallet string, bps int64) {
	w, v := whitelistBps.GetByIndex(index)
	return w, v.(int64)
}

// EffectivePrice returns what caller actually owes for a mint right
// now. Checks, in order: (1) the permanent individual whitelistBps
// override, (2) an active ../campaign discount, (3) the standard
// mintPriceUgnot. A plain cross-realm READ into campaign -- no cur
// needed, and campaign.Peek doesn't consume anything, so calling this
// repeatedly (e.g. to show a live price in a UI) is free of side
// effects.
func EffectivePrice(caller address) int64 {
	if v, ok := whitelistBps.Get(caller.String()).(int64); ok {
		return mintPriceUgnot * v / 10000
	}
	if bps, _, ok := campaign.Peek(caller); ok {
		return mintPriceUgnot * bps / 10000
	}
	return mintPriceUgnot
}

/* -------------------------------- owner-gated -------------------------------- */

func callerAddress() address {
	return unsaferealm.PreviousRealm().Address()
}

func assertOwner() {
	if callerAddress() != collectionOwner {
		panic("unauthorized: caller is not the collection owner")
	}
}

func SetApprovedVersion(cur realm, pkgpath string) {
	assertOwner()
	approvedVersion = pkgpath
}

func SetMintPrice(cur realm, ugnot int64) {
	assertOwner()
	if ugnot < 0 {
		panic("price cannot be negative")
	}
	mintPriceUgnot = ugnot
}

func AddToWhitelist(cur realm, wallet address, bps int64) {
	assertOwner()
	if bps < 0 || bps > 10000 {
		panic("bps must be between 0 and 10000")
	}
	whitelistBps.Set(wallet.String(), bps)
}

func AddToWhitelistBatch(cur realm, walletsCSV string, bps int64) {
	assertOwner()
	if bps < 0 || bps > 10000 {
		panic("bps must be between 0 and 10000")
	}
	for _, w := range strings.Split(walletsCSV, ",") {
		w = strings.TrimSpace(w)
		if w == "" {
			continue
		}
		whitelistBps.Set(w, bps)
	}
}

func RemoveFromWhitelist(cur realm, wallet address) {
	assertOwner()
	whitelistBps.Remove(wallet.String())
}

/* ------------------------------- version-gated -------------------------------- */

func assertCallerIsApprovedVersion(cur realm) {
	caller := cur.Previous().PkgPath()
	if approvedVersion == "" {
		panic("no version realm has been approved yet")
	}
	if caller != approvedVersion {
		panic("unauthorized: caller is not the approved version realm")
	}
}

// RecordMint is the ONLY way a token gets minted. Only the approved
// version realm may call it. Reserves comboKey atomically with the
// mint (panics if already taken -- the version realm should have
// pre-checked via IsTraitComboAvailable, but this is the real,
// authoritative check), increments the recipient's mint count, and --
// if payer (the wallet that actually signed and paid for this mint,
// which may differ from to) doesn't have a permanent whitelistBps
// override -- spends one use of their campaign discount, if they have
// one. campaign.ConsumeDiscount safely no-ops (ok=false) when payer
// has no active campaign entry, so this is safe to call unconditionally.
func RecordMint(cur realm, to address, payer address, tid grc721.TokenID, metadata grc721.Metadata, comboKey string) grc721.TokenID {
	assertCallerIsApprovedVersion(cur)
	if mintedTraitCombos.Has(comboKey) {
		panic("trait combination already minted")
	}
	checkErr(nft.Mint(to, tid))
	checkErr(nft.SetTokenMetadata(to, tid, metadata))
	mintedTraitCombos.Set(comboKey, true)
	tokenComboKeys.Set(tid.String(), comboKey)
	mintCountByWallet.Set(to.String(), MintsByWallet(to)+1)
	mintedIDs = append(mintedIDs, tid)
	if _, hasOverride := whitelistBps.Get(payer.String()).(int64); !hasOverride {
		campaign.ConsumeDiscount(cross(cur), payer)
	}
	return tid
}

// ReportMintingOpen/ReportMaxMintsPerWallet let the approved version
// realm mirror its own live settings here for display only -- see
// mintingOpenMirror's own doc comment for why this exists instead of a
// direct cross-realm read.
func ReportMintingOpen(cur realm, open bool) {
	assertCallerIsApprovedVersion(cur)
	mintingOpenMirror = open
}

func ReportMaxMintsPerWallet(cur realm, max int64) {
	assertCallerIsApprovedVersion(cur)
	maxMintsPerWalletMirror = max
}

/* -------------------------- Token-owner actions --------------------------- */

func Approve(cur realm, to address, tid grc721.TokenID) {
	checkErr(nft.Approve(callerAddress(), to, tid))
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	checkErr(nft.SetApprovalForAll(callerAddress(), operator, approved))
}

func TransferFrom(cur realm, from, to address, tid grc721.TokenID) {
	checkErr(nft.TransferFrom(callerAddress(), from, to, tid))
}

func SafeTransferFrom(cur realm, from, to address, tid grc721.TokenID) {
	checkErr(nft.SafeTransferFrom(callerAddress(), from, to, tid))
}

// Burn destroys a token. Caller must be its current owner. RELEASES the
// token's trait combination back into mintedTraitCombos, looked up
// from tokenComboKeys (the exact key RecordMint reserved, not a
// reconstruction -- see that field's own comment on why it has to be
// stored verbatim). Combined with nft.Burn itself freeing the token's
// owner/metadata storage, this frees the maximum real bytes possible,
// which maximizes the automatic storage-deposit refund gno's own
// runtime sends back to whoever calls Burn.
func Burn(cur realm, tid grc721.TokenID) {
	caller := callerAddress()
	owner, err := nft.OwnerOf(tid)
	checkErr(err)
	if caller != owner {
		panic(grc721.ErrCallerIsNotOwner)
	}
	metadata, err := nft.TokenMetadata(tid)
	checkErr(err)

	key := tid.String()
	if comboKey, ok := tokenComboKeys.Get(key).(string); ok {
		mintedTraitCombos.Remove(comboKey)
		tokenComboKeys.Remove(key)
	}

	checkErr(nft.Burn(tid))

	burnedRecords.Set(key, burnRecord{
		BurnedBy:   caller,
		BurnHeight: runtime.ChainHeight(),
		Metadata:   metadata,
	})
	burnedIDs = append(burnedIDs, tid)
}

/* ------------------------------ gnoweb display ------------------------------ */

func traitsToCSV(attrs []grc721.Trait) string {
	pairs := make([]string, len(attrs))
	for i, a := range attrs {
		pairs[i] = a.TraitType + "=" + a.Value
	}
	return strings.Join(pairs, ";")
}

// TokenSummary returns tid, its current owner, and its metadata as one
// pipe-delimited line, each value base64-encoded -- same shape the
// original single-realm design used, for any off-chain UI that wants a
// gallery view without decoding Gno's own struct value syntax.
func TokenSummary(tid grc721.TokenID) (string, error) {
	owner, err := nft.OwnerOf(tid)
	if err != nil {
		return "", err
	}
	metadata, err := nft.TokenMetadata(tid)
	if err != nil {
		return "", err
	}
	enc := base64.StdEncoding
	fields := []string{
		tid.String(),
		owner.String(),
		enc.EncodeToString([]byte(metadata.Name)),
		enc.EncodeToString([]byte(metadata.Description)),
		enc.EncodeToString([]byte(metadata.Image)),
		enc.EncodeToString([]byte(metadata.ExternalURL)),
		enc.EncodeToString([]byte(traitsToCSV(metadata.Attributes))),
		enc.EncodeToString([]byte(metadata.BackgroundColor)),
	}
	return strings.Join(fields, "|"), nil
}

// CollectionSummary returns one TokenSummary line per token on the
// given page (1-indexed, newest first, homeRenderLimit per page --
// same page size Render's own listing uses), newline-separated.
// Paginated because an unbounded version runs out of gas past a few
// dozen tokens (confirmed live in the original single-realm design at
// ~21 tokens) -- each summary re-embeds a full rendered image.
func CollectionSummary(page int) string {
	total := len(mintedIDs)
	if page < 1 {
		page = 1
	}
	startK := (page - 1) * homeRenderLimit
	endK := startK + homeRenderLimit
	if endK > total {
		endK = total
	}
	var lines []string
	for k := startK; k < endK; k++ {
		tid := mintedIDs[total-1-k]
		line, err := TokenSummary(tid)
		if err != nil {
			continue // burned since minting
		}
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n")
}

const walletScanChunk = 100

// WalletSummary is CollectionSummary filtered to owner, scanning at
// most walletScanChunk of mintedIDs starting at startIdx. Returns the
// matching lines plus nextIdx to resume from; nextIdx == TokenCount()
// once nothing is left to check.
func WalletSummary(owner address, startIdx int64) (summary string, nextIdx int64) {
	total := len(mintedIDs)
	start := int(startIdx)
	if start < 0 {
		start = 0
	}
	end := start + walletScanChunk
	if end > total {
		end = total
	}
	var lines []string
	for k := start; k < end; k++ {
		tid := mintedIDs[total-1-k]
		tokenOwner, err := nft.OwnerOf(tid)
		if err != nil || tokenOwner != owner {
			continue
		}
		line, err := TokenSummary(tid)
		if err != nil {
			continue
		}
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n"), int64(end)
}

// BurnedTokenSummary returns a permanent snapshot of one burned token,
// same line shape as TokenSummary, with owner swapped for
// burnedBy/burnHeight.
func BurnedTokenSummary(tid grc721.TokenID) (string, error) {
	raw := burnedRecords.Get(tid.String())
	rec, ok := raw.(burnRecord)
	if !ok {
		return "", grc721.ErrInvalidTokenId
	}
	enc := base64.StdEncoding
	fields := []string{
		tid.String(),
		rec.BurnedBy.String(),
		ufmt.Sprintf("%d", rec.BurnHeight),
		enc.EncodeToString([]byte(rec.Metadata.Name)),
		enc.EncodeToString([]byte(rec.Metadata.Description)),
		enc.EncodeToString([]byte(rec.Metadata.Image)),
		enc.EncodeToString([]byte(rec.Metadata.ExternalURL)),
		enc.EncodeToString([]byte(traitsToCSV(rec.Metadata.Attributes))),
		enc.EncodeToString([]byte(rec.Metadata.BackgroundColor)),
	}
	return strings.Join(fields, "|"), nil
}

// bigTokenImage scales up image's declared width/height for display on
// its own token page -- the viewBox (and therefore every internal
// coordinate) is untouched, so the browser just renders the same piece
// bigger, nothing is re-rendered.
func bigTokenImage(image string) string {
	const prefix = "data:image/svg+xml;base64,"
	if !strings.HasPrefix(image, prefix) {
		return image
	}
	raw, err := base64.StdEncoding.DecodeString(image[len(prefix):])
	if err != nil {
		return image
	}
	svg := string(raw)
	resized := strings.Replace(svg, `width="170.00" height="170.00"`, `width="`+tokenPageImageSize+`" height="`+tokenPageImageSize+`"`, 1)
	if resized == svg {
		resized = strings.Replace(svg, `width="170" height="170"`, `width="`+tokenPageImageSize+`" height="`+tokenPageImageSize+`"`, 1)
	}
	return prefix + base64.StdEncoding.EncodeToString([]byte(resized))
}

func renderMintedListPage(b *strings.Builder, page int) {
	total := len(mintedIDs)
	if total == 0 {
		return
	}
	totalPages := (total + homeRenderLimit - 1) / homeRenderLimit
	if page < 1 {
		page = 1
	}
	if page > totalPages {
		page = totalPages
	}
	startK := (page - 1) * homeRenderLimit
	endK := startK + homeRenderLimit
	if endK > total {
		endK = total
	}

	b.WriteString("\n## Minted so far\n\n")
	if totalPages > 1 {
		b.WriteString(ufmt.Sprintf("_page %d of %d -- %d minted total_\n\n", page, totalPages, total))
	}
	b.WriteString("| Image | Index | Name | Owner |\n|---|---|---|---|\n")
	for k := startK; k < endK; k++ {
		tid := mintedIDs[total-1-k]
		owner, err := nft.OwnerOf(tid)
		if err != nil {
			continue // burned
		}
		metadata, _ := nft.TokenMetadata(tid)
		name := metadata.Name
		if name == "" {
			name = "Untitled"
		}
		link := realmRelPath + ":token/" + tid.String()
		image := metadata.Image
		if image == "" {
			image = metadata.ImageData
		}
		imgCell := ""
		if image != "" {
			imgCell = ufmt.Sprintf("[![%s](%s)](%s)", name, image, link)
		}
		b.WriteString(ufmt.Sprintf("| %s | [#%s](%s) | %s | %s |\n", imgCell, tid.String(), link, name, owner))
	}
	b.WriteString("\n")

	renderPageLinks(b, page, totalPages, "page")
}

func renderPageLinks(b *strings.Builder, page, totalPages int, linkBase string) {
	if totalPages <= 1 {
		return
	}
	b.WriteString("\n")
	parts := []string{}
	if page > 1 {
		parts = append(parts, ufmt.Sprintf("[<< First](%s:%s/1)", realmRelPath, linkBase))
		parts = append(parts, ufmt.Sprintf("[<- newer](%s:%s/%d)", realmRelPath, linkBase, page-1))
	}
	lastShown := 0
	for p := 1; p <= totalPages; p++ {
		if p != 1 && p != totalPages && (p < page-pageWindow || p > page+pageWindow) {
			continue
		}
		if lastShown != 0 && p != lastShown+1 {
			parts = append(parts, "...")
		}
		if p == page {
			parts = append(parts, ufmt.Sprintf("**%d**", p))
		} else {
			parts = append(parts, ufmt.Sprintf("[%d](%s:%s/%d)", p, realmRelPath, linkBase, p))
		}
		lastShown = p
	}
	if page < totalPages {
		parts = append(parts, ufmt.Sprintf("[older ->](%s:%s/%d)", realmRelPath, linkBase, page+1))
		parts = append(parts, ufmt.Sprintf("[Last >>](%s:%s/%d)", realmRelPath, linkBase, totalPages))
	}
	b.WriteString(strings.Join(parts, " - "))
	b.WriteString("\n")
}

func renderBurnedListPage(b *strings.Builder, page int) {
	total := len(burnedIDs)
	if total == 0 {
		return
	}
	totalPages := (total + homeRenderLimit - 1) / homeRenderLimit
	if page < 1 {
		page = 1
	}
	if page > totalPages {
		page = totalPages
	}
	startK := (page - 1) * homeRenderLimit
	endK := startK + homeRenderLimit
	if endK > total {
		endK = total
	}

	b.WriteString("\n## Burned tokens\n\n")
	if totalPages > 1 {
		b.WriteString(ufmt.Sprintf("_page %d of %d -- %d burned total_\n\n", page, totalPages, total))
	}
	b.WriteString("| Image | Index | Name | Burned By | Block |\n|---|---|---|---|---|\n")
	for k := startK; k < endK; k++ {
		tid := burnedIDs[total-1-k]
		raw := burnedRecords.Get(tid.String())
		rec, ok := raw.(burnRecord)
		if !ok {
			continue
		}
		name := rec.Metadata.Name
		if name == "" {
			name = "Untitled"
		}
		image := rec.Metadata.Image
		if image == "" {
			image = rec.Metadata.ImageData
		}
		imgCell := ""
		if image != "" {
			imgCell = ufmt.Sprintf("![%s](%s)", name, image)
		}
		b.WriteString(ufmt.Sprintf("| %s | #%s | %s | %s | %d |\n", imgCell, tid.String(), name, rec.BurnedBy, rec.BurnHeight))
	}
	b.WriteString("\n")

	renderPageLinks(b, page, totalPages, "burned/page")
}

func render404() string {
	return ufmt.Sprintf("# 404\n\n[<- back to collection](%s)\n", realmRelPath)
}

func Render(path string) string {
	if path == "" {
		var b strings.Builder
		b.WriteString(nft.RenderHome())
		b.WriteString("\n## About\n\n")
		b.WriteString("Each Gem's Chain trait names a real gno.land testnet -- one of the generations that carried the network forward on its way to Mainnet. Set in a ring with its own small antigravity field, every piece is a keepsake for everyone who helped build, test, and grow gno.land into what it's becoming.\n\n")
		b.WriteString("This collection is also a demonstration: every gem is generative art, assembled fresh on each read and stored entirely on-chain -- no external links, nothing that can go missing.\n\n")
		b.WriteString(ufmt.Sprintf("* **Owner**: %s\n", Owner()))
		b.WriteString(ufmt.Sprintf("* **Assembled trait combinations minted**: %d\n", int64(mintedTraitCombos.Size())))
		b.WriteString("* **Max supply**: unlimited\n")
		if mintingOpenMirror {
			b.WriteString("* **Minting**: open\n")
		} else {
			b.WriteString("* **Minting**: closed\n")
		}
		if mintPriceUgnot > 0 {
			b.WriteString(ufmt.Sprintf("* **Mint price**: %d ugnot\n", mintPriceUgnot))
		} else {
			b.WriteString("* **Mint price**: free\n")
		}
		if maxMintsPerWalletMirror > 0 {
			b.WriteString(ufmt.Sprintf("* **Max mints per wallet**: %d\n", maxMintsPerWalletMirror))
		} else {
			b.WriteString("* **Max mints per wallet**: unlimited\n")
		}
		if len(burnedIDs) > 0 {
			b.WriteString(ufmt.Sprintf("* **Burned**: %d -- [view burned tokens ->](%s:burned)\n", len(burnedIDs), realmRelPath))
		}

		renderMintedListPage(&b, 1)
		return b.String()
	}

	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "page" {
		page, err := strconv.Atoi(parts[1])
		if err != nil || page < 1 {
			return render404()
		}
		var b strings.Builder
		b.WriteString(ufmt.Sprintf("# %s -- minted tokens\n\n[<- back to collection](%s)\n", nft.Name(), realmRelPath))
		renderMintedListPage(&b, page)
		return b.String()
	}
	if parts[0] == "burned" {
		page := 1
		if len(parts) == 3 && parts[1] == "page" {
			p, err := strconv.Atoi(parts[2])
			if err != nil || p < 1 {
				return render404()
			}
			page = p
		} else if len(parts) != 1 {
			return render404()
		}
		var b strings.Builder
		b.WriteString(ufmt.Sprintf("# %s -- burned tokens\n\n[<- back to collection](%s)\n", nft.Name(), realmRelPath))
		renderBurnedListPage(&b, page)
		return b.String()
	}
	if len(parts) == 2 && parts[0] == "token" {
		tid := grc721.TokenID(parts[1])
		owner, err := nft.OwnerOf(tid)
		if err != nil {
			return render404()
		}
		metadata, _ := nft.TokenMetadata(tid)
		var b strings.Builder
		b.WriteString(ufmt.Sprintf("# %s #%s\n\n[<- back to collection](%s)\n\n", nft.Name(), tid.String(), realmRelPath))
		image := metadata.Image
		if image == "" {
			image = metadata.ImageData
		}
		name := metadata.Name
		if name == "" {
			name = "Untitled"
		}
		if image != "" {
			b.WriteString(ufmt.Sprintf("![%s](%s)\n\n", name, bigTokenImage(image)))
		}

		b.WriteString("## Details\n\n")
		b.WriteString(ufmt.Sprintf("* **Collection**: %s\n", nft.Name()))
		b.WriteString(ufmt.Sprintf("* **Name**: %s\n", name))
		b.WriteString(ufmt.Sprintf("* **Index**: #%s\n", tid.String()))
		if metadata.Description != "" {
			b.WriteString(ufmt.Sprintf("* **Description**: %s\n", metadata.Description))
		}
		b.WriteString(ufmt.Sprintf("* **Owner**: %s\n", owner))

		if len(metadata.Attributes) > 0 {
			b.WriteString("\n## Traits\n\n")
			for _, attr := range metadata.Attributes {
				b.WriteString(ufmt.Sprintf("* **%s**: %s\n", attr.TraitType, attr.Value))
			}
		}
		return b.String()
	}

	return render404()
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

// Package gems4 (deployed at .../gems4/v1 -- gno's own /vN convention
// requires the package name to match the segment before the suffix)
// is the mint-mechanics half of the Gems split-realm design: trait
// assembly, on-chain SVG rendering, and chain-roster management live
// here and can be redeployed and re-approved at will, with zero
// holder migration, because ownership, pricing, discounts, AND trait-
// uniqueness history all live permanently in ../stable instead. No
// reveal delay: a mint's real metadata is visible immediately.
package gems4

import (
	"chain"
	"chain/banker"
	runtime "chain/runtime"
	unsaferealm "chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/base64"
	"strings"

	gemsart "gno.land/p/g17cjym5e9hhws46lt6329pv2gtx2ay0503hgems/gemsart2"
	grc721 "gno.land/p/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/grc721v2"
	stable "gno.land/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/gems4/stable"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

var (
	// collectionOwnerHere administers mint mechanics (rosters,
	// minting-open, wallet cap) -- pricing/discount administration
	// lives on ../stable and ../campaign instead. Same address as
	// stable's own collectionOwner; kept as a plain local constant
	// here rather than a cross-realm read on every assertOwner call.
	collectionOwnerHere address = "g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku"

	// mintingOpen is the owner's kill switch on new mints. Mirrored to
	// stable via ReportMintingOpen on every change (see that function's
	// own doc comment) purely so stable's Render() can show it.
	mintingOpen = true

	// maxMintsPerWallet caps how many tokens a single recipient may
	// receive -- 0 means unlimited. Mirrored to stable via
	// ReportMaxMintsPerWallet on every change. Actual per-wallet counts
	// are tracked on stable now (stable.MintsByWallet), not here.
	maxMintsPerWallet int64 = 3

	nextID seqid.ID
)

// traitPreset is one token's small trait selection for the
// assembled-on-read path -- holds just enough for gemsart to
// reconstruct the full image at mint time.
type traitPreset struct {
	Chain    string
	ShapeIdx int
	ColorIdx int
	Metal    string
	Active   bool
}

/* -------------------------------- Minting ---------------------------------- */

// MintAssembled is the collection's only mint path: assembles a fresh
// random (chain, shape, color, metal, active) combination, verifies
// payment against ../stable's discount-adjusted price for the caller
// (stable checks its own permanent whitelist, then ../campaign's
// temporary discount list), then records the mint on ../stable (the
// only place ownership, pricing, AND trait-uniqueness history
// actually live).
func MintAssembled(cur realm, to address) grc721.TokenID {
	if !mintingOpen {
		panic("minting is closed")
	}
	if maxMintsPerWallet > 0 && callerAddress() != collectionOwnerHere && stable.MintsByWallet(to) >= maxMintsPerWallet {
		panic(ufmt.Sprintf("wallet %s has already reached the %d-mint limit for this collection", to.String(), maxMintsPerWallet))
	}

	// Payment check is INLINED here (not factored into a helper) for the
	// same reason it was inlined in the original single-realm design:
	// chain/runtime.AssertOriginCall counts real call frames between the
	// origin MsgCall and itself, and a separate helper function adds
	// exactly one hop too many. This realm is the direct target of the
	// origin call (the user calls MintAssembled directly, which then
	// calls stable.RecordMint) so the frame-sensitive checks belong
	// here, not in stable.
	//
	// requiredPrice comes from stable.EffectivePrice -- a plain
	// cross-realm READ (no cur needed), so calling it adds no frame
	// before AssertOriginCall below.
	caller := callerAddress()
	requiredPrice := stable.EffectivePrice(caller)
	if requiredPrice != 0 {
		runtime.AssertOriginCall()
		if !unsaferealm.PreviousRealm().IsUserCall() {
			panic("payment verification requires a direct user call")
		}
		got := unsaferealm.OriginSend().AmountOf("ugnot")
		if got != requiredPrice {
			panic(ufmt.Sprintf("payment required: exactly %d ugnot, got %d", requiredPrice, got))
		}
		// Forwarded straight to stable's registered owner, same
		// auto-forward pattern the original single-realm design used.
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(cur.Address(), stable.Owner(), chain.Coins{{Denom: "ugnot", Amount: got}})
	}

	tp, comboKey := assembleUniqueTraits()

	tid := grc721.TokenID(nextID.String())
	metadata := assembledMetadata(tid, tp)

	// The actual mint + storage write + uniqueness reservation happens
	// on stable, atomically -- this is the version-gate boundary the
	// whole split exists to prove. cross(cur) required: calling ANOTHER
	// realm's crossing function needs it, not bare cur. caller is
	// passed as the separate payer arg -- RecordMint spends a
	// ../campaign discount use (if any) against WHOEVER PAID, which is
	// caller, not necessarily the mint recipient to.
	stable.RecordMint(cross(cur), to, caller, tid, metadata, comboKey)

	nextID.Next()

	return tid
}

// assembledMetadata renders tp's full metadata by calling gemsart's
// on-chain generator -- no reveal step in this build, so this runs at
// mint time and the result is visible immediately.
func assembledMetadata(tid grc721.TokenID, tp traitPreset) grc721.Metadata {
	svg, stone, _, colorName := gemsart.RenderTokenSVG(tp.Chain, tp.Metal, tp.ShapeIdx, tp.ColorIdx, tp.Active, tid.String())
	shapeName := gemsart.ShapeNames[tp.ShapeIdx]
	if stone == "Pearl" {
		shapeName = gemsart.PearlShapeNames[tp.ShapeIdx]
	}
	image := "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
	status := "Sunset"
	if tp.Active {
		status = "Active"
	}
	attrs := []grc721.Trait{
		{TraitType: "Chain", Value: tp.Chain + " Chain"},
		{TraitType: "Stone", Value: stone},
		{TraitType: "Shape", Value: shapeName},
		{TraitType: "Color", Value: colorName},
		{TraitType: "Metal", Value: tp.Metal + " Ring"},
		{TraitType: "Status", Value: status},
	}
	return grc721.Metadata{
		Name:            gemDisplayName(colorName, stone, shapeName, tp.Metal, tp.Chain),
		Description:     ufmt.Sprintf("A %s %s set in %s, minted on %s.", colorName, shapeName, tp.Metal, tp.Chain),
		Image:           image,
		BackgroundColor: "0a0b10",
		Attributes:      attrs,
	}
}

func gemDisplayName(colorName, stone, shape, metal, chain string) string {
	kind := stone
	if kind == "" || kind == "Not Set" {
		kind = "Gem"
	}
	return colorName + " " + kind + " " + shape + " -- " + metal + " Ring - " + chain + " Chain"
}

func traitComboKey(chainName string, shapeIdx, colorIdx int, metal string, active bool) string {
	return ufmt.Sprintf("%s|%d|%d|%s|%t", chainName, shapeIdx, colorIdx, metal, active)
}

const activeProbability = 0.2

type prng struct {
	seed string
	n    int
}

func newPRNG(seed string) *prng { return &prng{seed: seed} }

func (p *prng) next() uint64 {
	p.n++
	material := ufmt.Sprintf("%s:%d", p.seed, p.n)
	sum := sha256.Sum256([]byte(material))
	var v uint64
	for i := 0; i < 8; i++ {
		v = v<<8 | uint64(sum[i])
	}
	return v
}

func (p *prng) floatIn(lo, hi float64) float64 {
	frac := float64(p.next()%1000000) / 1000000.0
	return lo + frac*(hi-lo)
}

func (p *prng) intn(n int) int {
	if n <= 1 {
		return 0
	}
	return int(p.next() % uint64(n))
}

func randomTraitPreset(attempt int) traitPreset {
	material := ufmt.Sprintf("assemble:%d:%d:%s:%d",
		runtime.ChainHeight(), uint64(nextID), callerAddress().String(), attempt)
	rnd := newPRNG(material)

	chainName := chainRoster[rnd.intn(len(chainRoster))]
	stone := gemsart.StoneForChain(chainName)
	colorIdx := rnd.intn(gemsart.ColorPaletteSize(stone))
	shapeCount := len(gemsart.ShapeNames)
	if stone == "Pearl" {
		shapeCount = len(gemsart.PearlShapeNames)
	}
	shapeIdx := rnd.intn(shapeCount)
	metal := gemsart.MetalNames[rnd.intn(len(gemsart.MetalNames))]
	activeDraw := rnd.floatIn(0, 1) < activeProbability
	active := chainName == "MAINNET" || activeDraw

	return traitPreset{
		Chain:    chainName,
		ShapeIdx: shapeIdx,
		ColorIdx: colorIdx,
		Metal:    metal,
		Active:   active,
	}
}

const maxAssembleAttempts = 200

// assembleUniqueTraits draws candidates and pre-checks each against
// stable.IsTraitComboAvailable (a cross-realm READ -- uniqueness
// history lives on stable now, see that package's own doc comment).
// This is a pre-check, not the authoritative one: stable.RecordMint
// re-checks and reserves atomically with the actual mint. No race is
// possible between the two within the same call -- gno.land executes
// one transaction at a time, so nothing else can run between this
// check and RecordMint's own.
func assembleUniqueTraits() (traitPreset, string) {
	for attempt := 0; attempt < maxAssembleAttempts; attempt++ {
		tp := randomTraitPreset(attempt)
		key := traitComboKey(tp.Chain, tp.ShapeIdx, tp.ColorIdx, tp.Metal, tp.Active)
		if stable.IsTraitComboAvailable(key) {
			return tp, key
		}
	}
	panic("could not find an unused trait combination after many attempts -- the collection may be fully minted")
}

func IsTraitComboAvailable(chainName string, shapeIdx, colorIdx int, metal string, active bool) bool {
	key := traitComboKey(chainName, shapeIdx, colorIdx, metal, active)
	return stable.IsTraitComboAvailable(key)
}

func MaxUniqueTraitCombos() int64 {
	var total int64
	for _, chainName := range chainRoster {
		stone := gemsart.StoneForChain(chainName)
		shapeCount := len(gemsart.ShapeNames)
		if stone == "Pearl" {
			shapeCount = len(gemsart.PearlShapeNames)
		}
		total += int64(gemsart.ColorPaletteSize(stone)) * int64(shapeCount)
	}
	return total * int64(len(gemsart.MetalNames)) * 2
}

